   var root=Directory.GetParent(Application.dataPath)?.FullName??string.Empty;var contract=Path.Combine(root,"Packages","com.gamecreate.benchmark.noir-roombreak.contracts","Runtime","INoirRoombreakProbe.cs");var dashboardContract=Path.Combine(root,"Packages","com.gamecreate.benchmark.noir-roombreak.contracts","Runtime","GameStateDashboardV2.cs");var naming=Path.Combine(root,"Assets","Resources","naming-tables.json");var catalogJson=Path.Combine(root,"ASSET_CATALOG.json");var catalogMd=Path.Combine(root,"ASSET_CATALOG.md");var publicBaseline=File.Exists(contract)&&File.Exists(dashboardContract)&&File.Exists(naming)&&File.Exists(catalogJson)&&File.Exists(catalogMd);
