  static bool DashboardOk(IGameStateDashboard dashboard,out string observed){observed="dashboard=null";if(dashboard==null)return false;try{var s=dashboard.Capture();if(s==null)return false;var slotNames=(s.slots??new System.Collections.Generic.List<SlotEntry>()).Select(x=>x?.name??"").ToArray();var targets=s.targets??new System.Collections.Generic.List<TargetEntry>();var entities=s.entities??new System.Collections.Generic.List<EntityEntry>();var json=DashboardJson.ToJson(s);var strict=!json.Contains("\"id\":")&&!json.Contains("\"room\":")&&!json.Contains("\"visible\":true,\"id\"");var ok=dashboard.ContractVersion=="game-state-dashboard/v2"&&s.phase!=GamePhase.NotReady&&slotNames.Distinct(StringComparer.Ordinal).Count()==slotNames.Length&&Slots.All(x=>slotNames.Contains(x,StringComparer.Ordinal))&&targets.Select(x=>x.kind).Distinct(StringComparer.Ordinal).Count()==targets.Count&&new[]{"start_button","pause_resume_control","success_return_control","restart_button"}.All(x=>targets.Any(t=>t.kind==x))&&entities.All(x=>x!=null&&x.cell!=null&&x.cell.Length==2)&&strict;observed=$"version={dashboard.ContractVersion};phase={s.phase};slots={slotNames.Length};entities={entities.Count};targets={targets.Count};strict={strict}";return ok;}catch(Exception ex){observed=ex.GetType().Name;return false;}}
  static bool Cross(IGameStateDashboard dashboard,INoirRoombreakProbe probe,out string observed){observed="cross-failed";try{var s=dashboard.Capture();var slots=s.slots.ToDictionary(x=>x.name,x=>x.value,StringComparer.Ordinal);bool V(string n,float v)=>slots.TryGetValue(n,out var a)&&Mathf.Abs(a-v)<.001f;var phase=probe.CurrentScreen==NoirScreen.Menu?GamePhase.Menu:probe.CurrentScreen==NoirScreen.Playing?GamePhase.Playing:probe.CurrentScreen==NoirScreen.Paused?GamePhase.Paused:GamePhase.Won;var slotOk=s.phase==phase&&V("room_index",probe.CurrentRoomIndex)&&V("room_count",probe.RoomCount)&&V("bonds",probe.Bonds)&&V("maximum_bonds",probe.MaximumBonds)&&V("dash_charges",probe.DashCharges)&&V("maximum_dash_charges",probe.MaximumDashCharges)&&V("player_alive",probe.PlayerAlive?1:0)&&V("player_grounded",probe.PlayerGrounded?1:0)&&V("player_dashing",probe.PlayerDashing?1:0)&&V("player_invulnerable",probe.PlayerInvulnerable?1:0)&&V("anda_chasing",probe.AndaChasing?1:0)&&V("obser_lock_visible",probe.ObserLockVisible?1:0)&&V("obser_laser_visible",probe.ObserLaserVisible?1:0)&&V("defeated_enemy_count",probe.DefeatedEnemyCount)&&V("soft_respawn_count",probe.SoftRespawnCount)&&V("global_respawn_count",probe.GlobalRespawnCount)&&V("last_respawn_kind",(int)probe.LastRespawnKind)&&V("state_sequence",probe.StateSequence);var targets=s.targets??new System.Collections.Generic.List<TargetEntry>();var start=targets.FirstOrDefault(x=>x!=null&&x.kind=="start_button");var nonStart=targets.Where(x=>x!=null&&x.kind!="start_button").ToArray();var startExpected=probe.CurrentScreen==NoirScreen.Menu;var targetOk=start!=null&&start.visible==startExpected&&start.interactable==startExpected&&(!startExpected||(start.rect.width>=20&&start.rect.height>=20&&RectDistance(start.rect,probe.StartButtonScreenRect)<=4f))&&nonStart.All(x=>!x.visible&&!x.interactable);var entityOk=(s.entities??new System.Collections.Generic.List<EntityEntry>()).Count==0;var ok=slotOk&&targetOk&&entityOk;observed=$"phase={s.phase}/{phase};slots={slots.Count}/18;slotOk={slotOk};targetOk={targetOk};entityOk={entityOk};ok={ok}";return ok;}catch(Exception ex){observed=ex.GetType().Name;return false;}}
  static float RectDistance(Rect a,Rect b)=>Mathf.Abs(a.x-b.x)+Mathf.Abs(a.y-b.y)+Mathf.Abs(a.width-b.width)+Mathf.Abs(a.height-b.height);
  static bool SessionOk(MonoBehaviour[] behaviours,out string detail){
   detail="session unavailable";
   try{
    var ports=behaviours.OfType<IGameSession>().ToArray();if(ports.Length!=1)return false;
    var model=JsonUtility.FromJson<SessionModel>(Resources.Load<TextAsset>("session-model").text);var p=ports[0];
    if(p.EntryIds==null||p.EntryIds.Count!=model.entries.Length||!p.EntryIds.OrderBy(x=>x).SequenceEqual(model.entries.OrderBy(x=>x)))return false;
    var d=new SessionDriver(p,model,true);d.CheckDetachedCapture();var save=d.Observe();
    if(save.actors.Count(x=>x.kind=="player")!=1||save.actors.Count(x=>x.kind=="bench")!=1)return false;
    for(var room=0;room<5;room++){
     var actors=save.actors.Where(x=>x.entryId==model.entries[room]);
     if(room!=2&&!actors.Any(x=>x.kind=="anda")||room>=2&&!actors.Any(x=>x.kind=="obser"))return false;
    }
    save.values.First().value=model.values.First(x=>x.name==save.values.First().name).minimum-1;
    d.CheckInvalidRestore(save);detail="public session catalogue, state schema, detached capture, campaign identities and atomic rejection verified";return true;
   }catch(Exception ex){detail=ex.ToString();return false;}
  }
